import{_ as t,I as a,g as o,j as i}from"./chunks/framework.CjoWWfVe.js";const p=JSON.parse('{"title":"Global Settings","description":"Changing the interface language, accounting currency, and data rescue/reset tools in OmniCraft ERP.","frontmatter":{"title":"Global Settings","description":"Changing the interface language, accounting currency, and data rescue/reset tools in OmniCraft ERP.","order":16},"headers":[],"relativePath":"docs/global-settings.md","filePath":"docs/global-settings.md"}'),n={name:"docs/global-settings.md"};function r(s,e,l,c,d,u){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="⚙️-global-settings-language-currency-and-security" tabindex="-1">⚙️ Global Settings: Language, Currency, and Security <a class="header-anchor" href="#⚙️-global-settings-language-currency-and-security" aria-label="Permalink to &quot;⚙️ Global Settings: Language, Currency, and Security&quot;">​</a></h1><p>Unlike <em>Workspace Settings</em>, which affect the economics of a specific business (rates, markups, overhead costs), <strong>Global Settings</strong> establish the fundamental rules of operation for the entire application and your local database.</p><p>To open them, click <strong>File ➔ Program Settings</strong> in the top menu.</p><hr><h2 id="🌍-localization-and-currency" tabindex="-1">🌍 Localization and Currency <a class="header-anchor" href="#🌍-localization-and-currency" aria-label="Permalink to &quot;🌍 Localization and Currency&quot;">​</a></h2><h3 id="_1-interface-language" tabindex="-1">1. Interface Language <a class="header-anchor" href="#_1-interface-language" aria-label="Permalink to &quot;1. Interface Language&quot;">​</a></h3><p>The program supports full interface localization. Upon its very first launch, OmniCraft ERP automatically scans your operating system&#39;s language and adapts to it. You can switch between <strong>Russian (RU)</strong> and <strong>English (EN)</strong> at any time.</p><ul><li><strong>How it works:</strong> Changing the language requires a full restart of the application so that all system windows, cash flow categories, and directories are properly translated and loaded from the dictionary databases.</li></ul><h3 id="_2-accounting-currency" tabindex="-1">2. Accounting Currency <a class="header-anchor" href="#_2-accounting-currency" aria-label="Permalink to &quot;2. Accounting Currency&quot;">​</a></h3><p>By default, the program pulls your national currency symbol from your OS regional settings (e.g., <code>₽</code>, <code>$</code>, <code>€</code>, <code>£</code>, <code>₺</code>). You can change it to any other currency using the convenient built-in search tool (just start typing the name, such as <em>“Euro”</em> or <em>“Lira”</em>).</p><div class="warning custom-block"><p class="custom-block-title">Protecting Historical Data</p><p>The currency change button is <strong>automatically locked</strong> as soon as you begin recording real transactions (the moment you register your first purchase, sale, or cash flow entry).</p><p>This is done to protect your financial reporting. If the program allowed you to switch currencies on the fly, all your previous receipts, balances, and analytical charts would instantly become a mathematical mess. <strong>What if you relocate to another country?</strong> You will need to perform an &quot;Accounting Reset&quot; (see below) to start keeping books in the new currency from a clean slate, while preserving your existing directories and recipes.</p></div><hr><h2 id="🤖-ai-features-core-ai-hub-byok" tabindex="-1">🤖 AI Features (Core AI Hub &amp; BYOK) <a class="header-anchor" href="#🤖-ai-features-core-ai-hub-byok" aria-label="Permalink to &quot;🤖 AI Features (Core AI Hub &amp; BYOK)&quot;">​</a></h2><p>OmniCraft ERP includes intelligent assistant features powered by artificial intelligence under the <strong>BYOK model (Bring Your Own Key)</strong>.</p><p>All requests to neural network providers are transmitted <strong>directly from your device</strong> to the provider&#39;s API. Your business records, proprietary recipes, client lists, and financial reports never pass through intermediate OmniCraft ERP proxy servers, ensuring 100% data privacy and security.</p><h3 id="_1-supported-ai-providers" tabindex="-1">1. Supported AI Providers <a class="header-anchor" href="#_1-supported-ai-providers" aria-label="Permalink to &quot;1. Supported AI Providers&quot;">​</a></h3><ul><li><strong>OpenAI</strong> (GPT-4o, GPT-4o-mini, o1, o3-mini);</li><li><strong>DeepSeek</strong> (DeepSeek-Chat, DeepSeek-Reasoner / R1);</li><li><strong>Google Gemini</strong> (Gemini 1.5 Flash, Gemini 1.5 Pro, Gemini 2.0);</li><li><strong>Anthropic</strong> (Claude 3.5 Sonnet, Claude 3.5 Haiku, Claude 3 Opus);</li><li><strong>OpenRouter</strong> (access to dozens of top models via a single API key);</li><li><strong>Custom Endpoint / Local Ollama</strong> (fully private and offline execution).</li></ul><p>AI settings are organized into a dedicated &quot;AI Agent&quot; tab in Program Settings with one-click deep linking from assistant shortcuts:</p><ul><li><strong>Isolated Per-Provider Configurations:</strong> Each neural network provider securely retains its own credentials, chosen model, and custom endpoint URL. Switching providers instantly restores their respective saved parameters, preventing credential collisions.</li><li><strong>Reactive Base URL &amp; Local Models:</strong> When working with local models (Ollama, LM Studio, or custom gateways), entering a custom Base URL automatically locks cloud dropdowns and activates a dedicated Model ID field directly below, accompanied by a helpful guidance tooltip <code>(?)</code>.</li><li><strong>Pure Model Filtering Without Ghost Items:</strong> The model selection dialog performs strict filtering over the provider&#39;s verified catalog without injecting search query text as synthetic model entries.</li><li><strong>Standardized Form Typography:</strong> Input fields for API keys, Base URLs, and Model IDs strictly adhere to the standard design system font size (13px), eliminating bloated password masking dots.</li><li><strong>Live Connection Diagnostics:</strong> The application continuously verifies endpoint connectivity in the background, showing a responsive animated progress ring and clear status badges.</li><li><strong>Self-Healing Vault:</strong> Migrating database files between computers triggers a non-disruptive key re-authorization prompt without application crashes.</li></ul><h3 id="_2-hardware-level-key-protection-windows-dpapi" tabindex="-1">2. Hardware-Level Key Protection (Windows DPAPI) <a class="header-anchor" href="#_2-hardware-level-key-protection-windows-dpapi" aria-label="Permalink to &quot;2. Hardware-Level Key Protection (Windows DPAPI)&quot;">​</a></h3><p>Your API key is encrypted on disk using native operating system cryptographic protection (<strong>Windows Data Protection API — DPAPI</strong>). The encrypted secret is bound to your user account and computer hardware, preventing unauthorized extraction by third-party utilities or configuration file leaks.</p><h3 id="_3-assistant-buttons-spark-buttons-✨-in-workspaces" tabindex="-1">3. Assistant Buttons (&quot;Spark Buttons&quot; ✨) in Workspaces <a class="header-anchor" href="#_3-assistant-buttons-spark-buttons-✨-in-workspaces" aria-label="Permalink to &quot;3. Assistant Buttons (&quot;Spark Buttons&quot; ✨) in Workspaces&quot;">​</a></h3><p>When AI is configured, smart assistant buttons become available in key modules:</p><ul><li><strong>Batch Calculator:</strong> in-depth cost structure audit, identification of main cost drivers, and batch pricing advice.</li><li><strong>Materials Warehouse:</strong> instant generation of technical item descriptions, specifications, and storage recommendations.</li><li><strong>Production Workbench:</strong> operational checklist for the craftsman with quality checkpoints and raw material risk assessments.</li></ul><p>If an API key is not yet configured, clicking any assistant button presents a gentle shortcut dialog to the Settings window without disrupting your current workflow. The application remains 100% functional without AI.</p><h3 id="_4-built-in-ai-assistant-right-sidebar-panel" tabindex="-1">4. Built-in AI Assistant (Right Sidebar Panel) <a class="header-anchor" href="#_4-built-in-ai-assistant-right-sidebar-panel" aria-label="Permalink to &quot;4. Built-in AI Assistant (Right Sidebar Panel)&quot;">​</a></h3><p>A sliding assistant panel is docked to the right edge of the main application window.</p><ul><li><strong>Non-intrusive by Default:</strong> The panel remains collapsed into a slim 38px bar with a compact icon, never distracting the craftsman or cluttering the workspace.</li><li><strong>Screen Context Awareness:</strong> The assistant detects the active module (Warehouse, Workbench, Calculator, Sales) and grounds its responses in current stock and configuration. You can disable screen context at any time using the header toggle or click the preview icon to inspect the exact data snapshot sent to the model.</li><li><strong>Scope Selector (Active Tab vs Full App):</strong> An interactive badge in the panel header switches between &quot;🔒 Tab&quot; (strict isolation restricting tool calls to the active screen) and &quot;🌐 All System&quot; (smart cross-module routing with access to all registered tools).</li><li><strong>Human-in-the-Loop Safety (Zero-Destruction):</strong> When the assistant proposes an operational action (such as generating links or updating records), it presents a structured action card. Mutating operations are executed <strong>only after your explicit confirmation</strong> via the &quot;Execute&quot; button.</li><li><strong>Private Mode:</strong> When connected to a local model (such as Ollama), a green &quot;Offline&quot; badge confirms that processing takes place entirely on your device without internet transmission.</li></ul><h3 id="_5-global-ai-instruction" tabindex="-1">5. Global AI Instruction <a class="header-anchor" href="#_5-global-ai-instruction" aria-label="Permalink to &quot;5. Global AI Instruction&quot;">​</a></h3><p>The internal assistant&#39;s system prompt is assembled using a modular multi-tier pipeline:</p><ul><li><strong>Core Accounting Safeguards:</strong> Built-in craftsman mentor rules, accounting invariants (Moving Average Cost MAC for raw materials, FIFO write-offs for finished goods, integer scaling for currency), and the Zero-Destruction policy are strictly enforced by the program core.</li><li><strong>Workshop Specifics (System Context):</strong> A customizable profile in Program Settings pre-filled with an overarching craftsman manifesto (total cost of production, material and consumable accounting, labor time estimates, scrap allowances, and equipment depreciation). You can adapt this prompt to your specific craft at any time.</li><li><strong>Workspace Scope:</strong> Contextual guidelines tailored to the active workspace profile (Production, Services, Personal Capital).</li><li><strong>Tab Context:</strong> Targeted instructions for the active module (Warehouse, Workbench, Calculator, Sales, Cash Flow).</li><li><strong>Task Sparks:</strong> Contextual micro-prompts triggered by one-click spark buttons.</li></ul><p>Thanks to the Stable Prefix architecture, immutable system layers are cached by the LLM provider, dramatically cutting response latency and reducing token costs.</p><h3 id="_6-long-term-memory-self-learning-and-token-budgeting" tabindex="-1">6. Long-Term Memory, Self-Learning, and Token Budgeting <a class="header-anchor" href="#_6-long-term-memory-self-learning-and-token-budgeting" aria-label="Permalink to &quot;6. Long-Term Memory, Self-Learning, and Token Budgeting&quot;">​</a></h3><p>OmniCraft ERP includes a native long-term memory engine powered by lightweight local <code>SQLite FTS5</code> full-text search with BM25 ranking. The assistant learns craftsman habits, technical nuances, and workshop rules without heavy external libraries.</p><ul><li><strong>Learning Modes &amp; Autopilot:</strong> Program Settings provide an explicit toggle for automated assistant self-learning. Craftsmen can choose between interactive confirmation prompts or seamless autopilot mode without disruption.</li><li><strong>Token Budget &amp; Memory Compaction:</strong> To keep system prompts concise and responsive, rule memory features a configurable token limit (1,000 tokens by default). As memory fills, background compaction automatically prunes stale or low-confidence rules while preserving core workshop guidelines.</li><li><strong>Reflexion Learning Loop:</strong> When declining an action proposed by the assistant (clicking &quot;Cancel&quot; on an Action Card), a concise feedback dialog opens. If you specify the reason (e.g., <em>“We only package oil in 0.5 L bottles, never 1 L”</em>), the assistant formulates a rule and commits it to memory for that section, preventing repeated mistakes.</li><li><strong>Pinning Rules to Memory (Pin Icon 📌):</strong> Every assistant message features a compact pin button in its upper-right corner. You can pin key answers or manufacturing rules to long-term memory with a single click.</li><li><strong>Memory Inspector in Settings:</strong> The &quot;AI Agent&quot; tab in Program Settings provides a complete view of all learned rules. You can toggle rules on and off, delete obsolete items, or manually add new rules with global or tab-specific scope.</li><li><strong>Workspace Sandboxing:</strong> Rules originating from the Personal Capital module are strictly partitioned and never bleed into commercial workshop spaces.</li></ul><h3 id="_7-external-ai-agents-mcp-stdio-server" tabindex="-1">7. External AI Agents (MCP Stdio Server) <a class="header-anchor" href="#_7-external-ai-agents-mcp-stdio-server" aria-label="Permalink to &quot;7. External AI Agents (MCP Stdio Server)&quot;">​</a></h3><p>OmniCraft ERP supports the standardized Model Context Protocol (MCP, 2024-11-05 specification) for interaction with external autonomous agents. This enables external developer tools and agent clients (Cursor, Claude Desktop, Antigravity) to communicate directly with the application via local inter-process communication (<code>stdio</code>).</p><ul><li><strong>Unified Entry Point:</strong> All registered application modules expose their tools through a single central registry. An external agent connects with a single configuration snippet and accesses capabilities across the entire system.</li><li><strong>Pairing Token and One-Click Revocation:</strong> For secure pairing, the settings window generates a unique cryptographic pairing token. If you need to terminate agent access, simply click &quot;Revoke Token&quot;—external connections are immediately invalidated.</li><li><strong>Ready-to-Copy Configuration:</strong> Clicking &quot;Copy JSON Config&quot; generates a standard JSON configuration snippet ready for insertion into your agent configuration (<code>claude_desktop_config.json</code> or Cursor <code>mcp.json</code>).</li><li><strong>Trusted Mode (Protection Against Unauthorized Changes):</strong> By default, external agents are restricted to safe read-only operations. Any mutating operations (such as link generation or record updates) are blocked at the core registry level. To allow modifications, you must explicitly enable &quot;Trusted Mode&quot; in the Program Settings.</li><li><strong>End-to-End Audit Trail:</strong> Every agent invocation is recorded in the system audit log with caller identity, tool name, input arguments, status, and execution latency in milliseconds.</li></ul><h3 id="_8-hierarchical-skills-system-registries-help-➔-system-registries" tabindex="-1">8. Hierarchical Skills &amp; System Registries (Help ➔ System Registries) <a class="header-anchor" href="#_8-hierarchical-skills-system-registries-help-➔-system-registries" aria-label="Permalink to &quot;8. Hierarchical Skills &amp; System Registries (Help ➔ System Registries)&quot;">​</a></h3><p>The program provides a unified control center for automation workflows and system instruction inspection — the <strong>&quot;AI Skills &amp; Prompts Registry&quot;</strong>, accessible via the top menu <strong>Help ➔ System Registries</strong>.</p><ul><li><strong>Hierarchical Tree Navigation:</strong> The registry interface is organized into a three-tier tree (<code>Program ➔ Workspaces ➔ Tab Domains</code>). Selecting any node (such as Warehouse, Workshop, or Calculator) allows the craftsman to inspect the active system instruction for that level alongside its assigned scenarios.</li><li><strong>Skills Library (Reusable Scenarios):</strong> Each skill represents a pre-configured workflow template bound to a specific scope (<code>global</code>, <code>space</code>, or <code>tab</code>). You can toggle built-in skills on and off with switches or create custom scenarios using the &quot;+ New Skill&quot; button.</li><li><strong>Interactive Suggested Chips:</strong> Tab-level skills automatically populate as interactive chips at the top of the expanded assistant panel. As you switch modules, these chips instantly adapt to the active screen, enabling one-click raw material deficit audits or cost breakdown queries.</li><li><strong>Exporting AI Map to Markdown:</strong> The &quot;Export AI Map to Markdown&quot; button in the registry header generates a comprehensive, structured report covering all prompt tiers (L0–L3), the skills library, registered tools, and learned memory rules, copying it directly to the clipboard.</li></ul><h3 id="_9-pc-agent-mode-four-level-security-gate-hitl" tabindex="-1">9. PC Agent Mode &amp; Four-Level Security Gate (HITL) <a class="header-anchor" href="#_9-pc-agent-mode-four-level-security-gate-hitl" aria-label="Permalink to &quot;9. PC Agent Mode &amp; Four-Level Security Gate (HITL)&quot;">​</a></h3><p>To enable safe interaction between the AI assistant, the local filesystem, and operating system utilities, OmniCraft ERP incorporates a four-tier authorization gateway:</p><ul><li><strong>PC Agent Mode Toggle:</strong> By default, this mode is strictly disabled. While disabled in the assistant settings, the application unconditionally blocks any attempt to access external files or invoke OS commands.</li><li><strong>Allowed Directories Whitelist:</strong> You can specify trusted folder paths (e.g., <code>C:\\Reports; C:\\Exports</code>), restricting file operations exclusively to these locations. Direct access to system database files (<code>*.db</code>, <code>*.sqlite</code>) and environment secrets (<code>.env</code>) is categorically forbidden.</li><li><strong>Four-Level Authorization Matrix (Human-in-the-Loop):</strong><ul><li>🟢 <strong>Class 1 (ERP Read):</strong> Querying stock balances, calculating batch costs, and viewing analytics — executed automatically without disruptive prompts.</li><li>🟡 <strong>Class 2 (ERP Mutation):</strong> Deducting materials, registering sales, or booking cash flow entries — presented via an Action Card with &quot;Execute&quot; and &quot;Reject&quot; buttons.</li><li>🟠 <strong>Class 3 (Filesystem &amp; Hardware):</strong> Saving export reports, inspecting invoices, printing labels — requires explicit modal confirmation of the target path or printer device.</li><li>🔴 <strong>Class 4 (OS Execution / Critical Red):</strong> Executing system commands and external binaries — displayed within a blocking red security modal featuring full command inspection, Zero-Destruction Policy enforcement, and a mandatory 3-second delay timer on the confirmation button to prevent accidental clicks.</li></ul></li></ul><hr><h2 id="☢️-danger-zone" tabindex="-1">☢️ Danger Zone <a class="header-anchor" href="#☢️-danger-zone" aria-label="Permalink to &quot;☢️ Danger Zone&quot;">​</a></h2><p>At the bottom of the settings window, you will find tools for radical database interventions. These buttons should be used with extreme caution.</p><h3 id="🧹-accounting-reset-wiping-transaction-history" tabindex="-1">🧹 Accounting Reset (Wiping Transaction History) <a class="header-anchor" href="#🧹-accounting-reset-wiping-transaction-history" aria-label="Permalink to &quot;🧹 Accounting Reset (Wiping Transaction History)&quot;">​</a></h3><p>This tool is designed to <strong>&quot;zero out&quot; the operational memory</strong> of the business without losing its infrastructure. It is ideal if you have been using the program in a trial/test mode, recorded many test receipts, and now want to start keeping real books from a clean slate.</p><table tabindex="0"><thead><tr><th style="text-align:left;">What will be DELETED (Logs)</th><th style="text-align:left;">What will be ZEROED (Balances)</th><th style="text-align:left;">What will be SAVED (Infrastructure)</th></tr></thead><tbody><tr><td style="text-align:left;">• Entire sales history (receipts)</td><td style="text-align:left;">• Physical materials stock in warehouse</td><td style="text-align:left;">• All equipment &amp; assets (Workshop)</td></tr><tr><td style="text-align:left;">• Inventory movement logs</td><td style="text-align:left;">• Finished goods stock (Showcase)</td><td style="text-align:left;">• Materials directories &amp; supplier links</td></tr><tr><td style="text-align:left;">• Cash flow ledger (Cash Flow)</td><td style="text-align:left;">• Cash register balances &amp; Cash Flow history</td><td style="text-align:left;">• All product templates &amp; Recipes</td></tr><tr><td style="text-align:left;">• Production queue (Workbench)</td><td style="text-align:left;">• FIFO batch cost values</td><td style="text-align:left;">• Categories, pack types, global settings</td></tr></tbody></table><p>Prior to performing the wipe, the program will automatically create a shadow backup of the database. After clicking <strong>&quot;Clear History&quot;</strong> (Accounting Reset), OmniCraft ERP will prompt an automatic reboot. You will receive a clean workshop, ready for the initial stock inventory (see <a href="./getting-started">Quick Start</a>).</p><h3 id="💥-factory-reset" tabindex="-1">💥 Factory Reset <a class="header-anchor" href="#💥-factory-reset" aria-label="Permalink to &quot;💥 Factory Reset&quot;">​</a></h3><p>This is the &quot;red pill&quot; button—the ultimate database reset. It <strong>permanently deletes absolutely everything</strong> from your local SQLite database.</p><ul><li>All tables, directories, recipes, receipts, stock balances, settings, and license keys vanish completely.</li><li>Upon the next startup, the program will generate a brand new database, exactly as if you had just downloaded and installed OmniCraft ERP for the very first time.</li></ul><div class="danger custom-block"><p class="custom-block-title">Attention!</p><p>Before using this function, <strong>always</strong> make a manual data export (<code>File ➔ Export Data ➔ Backup Database .db</code>) if there is even a slight chance you might need this information in the future. Recovering data after a factory reset without a backup file is impossible.</p></div><hr><h2 id="🔄-automatic-reboot" tabindex="-1">🔄 Automatic Reboot <a class="header-anchor" href="#🔄-automatic-reboot" aria-label="Permalink to &quot;🔄 Automatic Reboot&quot;">​</a></h2><p>Any changes in the Global Settings (changing the language, currency, or resetting accounts) require a reconfiguration of the operational memory. After saving changes, the program will prompt you to <strong>reboot now</strong> or do it later.</p><p>During the reboot, OmniCraft ERP carefully preserves your window geometry (size and position on the screen), allowing you to resume your work exactly where you left off.</p>',59)])])}const h=t(n,[["render",r]]);export{p as __pageData,h as default};
